package br.com.marquesautodetail.api.security; import jakarta.servlet.*;import jakarta.servlet.http.*;import org.springframework.security.authentication.*;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.security.core.userdetails.UserDetails;import org.springframework.security.web.authentication.WebAuthenticationDetailsSource;import org.springframework.stereotype.Component;import org.springframework.web.filter.OncePerRequestFilter;import java.io.IOException;
@Component public class JwtAuthFilter extends OncePerRequestFilter{ private final JwtService jwt; private final CustomUserDetailsService uds; public JwtAuthFilter(JwtService jwt,CustomUserDetailsService uds){this.jwt=jwt;this.uds=uds;} protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain)throws ServletException,IOException{String h=req.getHeader("Authorization"); if(h!=null&&h.startsWith("Bearer ")){try{String token=h.substring(7);String email=jwt.getEmail(token); if(email!=null&&SecurityContextHolder.getContext().getAuthentication()==null){UserDetails ud=uds.loadUserByUsername(email); var auth=new UsernamePasswordAuthenticationToken(ud,null,ud.getAuthorities()); auth.setDetails(new WebAuthenticationDetailsSource().buildDetails(req)); SecurityContextHolder.getContext().setAuthentication(auth);}}catch(Exception ignored){}} chain.doFilter(req,res);} }
